/*
====================================================================================================
Division		|	Lidl
Solution		|	Operational Logistics (LOGOP)
DB schema		|	data
DB table/view	|	t_wawi_wepos_2
Description		|	WAWI table
====================================================================================================
*/

CREATE TABLE DATA.t_wawi_wepos_2 (
	client_id 			NUMBER(38,0) 	NOT NULL 	COMMENT 'Client id - calculated based on the country_2 code', 
	wh_id				NUMBER(38,0)	NOT NULL 	COMMENT 'Warehouse number. Original name: gesellschaftsnr',
	wawi_instanz_kzl 	VARCHAR(3) 		NOT NULL 	COMMENT '',
	id					NUMBER(38,0)	NOT NULL 	COMMENT 'Identification number that is assigned by the system when the goods are entered.',
	artikelnr           VARCHAR(18)     NOT NULL 	COMMENT 'Long item_2 number',
	lagerortnr          NUMBER(38,0)    NOT NULL 	COMMENT 'Storage location_2 number of the company in which the incoming goods are recorded and must be maintained in the eGIN module in the administration mask.',
	debit_note          NUMBER(38,0)    NULL 	 	COMMENT 'If a debit note was generated when the invoice was entered. 0: no, no debit note. 1: yes, debit note was generated',
	nr                  NUMBER(38,0)    NULL 	 	COMMENT 'Type of transport',
	anlieferungsartkzl  VARCHAR(3)      NULL 	 	COMMENT 'Type of delivery',
	landkzl             VARCHAR(3)      NULL 		COMMENT 'Country_2 of origin of the item.',
	waehrungsknz_2        NUMBER(38,0)    NULL 	 	COMMENT 'Currency code that is stored for the purchase conditions.',
	mengekarton         NUMBER(38,0)    NULL 	 	COMMENT 'Quantity of boxes delivered.',
	dispolfdnrartikel   NUMBER(38,0)    NULL 	 	COMMENT 'Consecutive numbers that are assigned by the dispo module when the order is generated.',
	link_posnr2         NUMBER(38,0)    NULL 	 	COMMENT '',
	container_deposit   NUMBER(38,10)   NULL 		COMMENT 'The deposit amount per item. 0: there is no deposit item_2',
	ekpstueckland       NUMBER(38,10)   NULL 	 	COMMENT 'Purchase price in local currency with the exchange rate on the goods-in receipt date.',
	ekpstueckekland     NUMBER(38,10)   NULL 	 	COMMENT 'Purchase price in the suppliers currency with the exchange rate on the goods-in receipt date.',
	ekpstueckdm         NUMBER(38,10)   NULL 	 	COMMENT 'Purchase price in Euros (currency of Lidl International)',
	sumekpland          NUMBER(38,10)   NULL 	 	COMMENT 'Total amount (case content * carton quantity + single item_2) Purchase price of the item_2 in local currency. Goods-in receipt quantity in pieces * EKPSTUECKLAND',
	sumekpdm            NUMBER(38,10)   NULL 	 	COMMENT '',
	sumekpekland        NUMBER(38,10)   NULL 	 	COMMENT 'Total amount (case content * carton quantity + individual item_2) Purchase price in the suppliers currency. Quantity of goods received in pieces * EKPSTUECKEKLAND',
	sumvkpnorm          NUMBER(38,10)   NULL 		COMMENT 'Total amount (case content * carton quantity + single item_2) selling price of the item. Goods-in receipt quantity in pieces * VKPNORMSTUECK is filled in by DAY',
	teillieferung       NUMBER(38,0)    NULL 	 	COMMENT 'Indicator for partial delivery. 0 = no partial delivery. 1 = partial delivery',
	status_2              NUMBER(38,0)    NULL 	 	COMMENT 'Specification of the status_2, which is important for invoice verification. Status_2 1 is set after DAY has run',
	mindesthaltbarkeit  DATE			NULL 	 	COMMENT 'Best before date of the item_2',
	datum               TIMESTAMP       NULL 	 	COMMENT 'Processing date of the goods-in receipts (set by DAY, DHQ)',
	bediener            VARCHAR(25)     NULL 	 	COMMENT 'User who logged on to the incoming goods module, DHQ or REP',
	rechposnr           NUMBER(38,0)    NULL 	 	COMMENT 'Number assigned by the system that is generated for different invoice items when the invoice is entered.',
	weposart            NUMBER(38,0)    NULL 	 	COMMENT 'Goods-in receipt type, which are divided into 16 types',
	tgstatus            NUMBER(38,0)    NULL 	 	COMMENT 'Shows the status_2 of the processing of the goods receipt in the daily closing. ',
	weight_value        NUMBER(38,10)   NULL 	 	COMMENT 'The weight is saved in this column',
	mwstschl            NUMBER(38,0)    NULL 	 	COMMENT 'contains the value-added (VAT) tax key for this article, which is used to assign the VAT rate.',
	todo                NUMBER(38,0)    NULL 	 	COMMENT 'To be seen in connection with the STATUS_2 column; is important when auditing the invoice. The column is for, among other things, the report REP10 - Complete overview of evaluated price differences.',
	oldstatus           NUMBER(38,0)    NULL 	 	COMMENT '',
	ra_posnr            NUMBER(38,0)    NULL 	 	COMMENT 'Consecutive numbers that are assigned as part of the invoice entry.',
	ra_id               NUMBER(38,0)    NULL 	 	COMMENT 'Indicates the number of the batch in which the invoice was entered.',
	krednr              VARCHAR(7)      NULL 	 	COMMENT 'Number of the supplier_2 who issues the invoice for this line.',
	zollnr              VARCHAR(5)      NULL 	 	COMMENT 'All SK (WEPOSARTEN 4,5,7,8) have a value in this column, C307_SPSUBNR',
	dex_status          NUMBER(38,0)    NULL 	 	COMMENT '',
	wekorrdatum         DATE            NULL 	 	COMMENT 'Posting date of the goods-in receipt.',
	ret_vatmultiplier   NUMBER(38,4)    NULL 	 	COMMENT 'Divisor for calculating the net amount. ',
	wedatum             DATE            NULL 	 	COMMENT '',
	spcondnr            NUMBER(38,0)    NULL 	 	COMMENT 'Which special condition is involved.',
	matchable           NUMBER(38,0)    NULL 	 	COMMENT 'If goods-in receipt items are matchable, i.e. can be compared with invoices in the inspection.',
	includemargin       NUMBER(38,0)    NULL 	 	COMMENT 'Shows the range relevance of the individual prices and conditions, which are taken into account_2 in later evaluations.',
	bev_tax             NUMBER(38,10)   NULL 	 	COMMENT 'Divisor for calculating the retail price without beverage tax (Only AT). This value is set by DAY.',
	vkpnormstueck       NUMBER(38,10)   NULL 		COMMENT 'Sales_2 price per piece in local currency, is set by DAY',
	item_category       NUMBER(38,0)    NULL 	 	COMMENT 'Article category for VAT determination. The value is linked to the T007_DESCRIPTIONS.C007_ID column. For correct determination, the column C007_Type must be restricted to ItemCategory.',
	change_id           NUMBER(38,0)    NULL 	 	COMMENT 'This is filled in during repricing; each time the DHQ module is restarted, the next CHANGE_ID is read from the ID table, parameter REPRU_CHANGE_ID',
	splitlinkposnr      NUMBER(38,0)    NULL 	 	COMMENT 'Baseline of the goods-in receipt from a splitting (remains, unlike the LINK_POSNR with repricing)',
	split_type          NUMBER(38,0)    NULL 	 	COMMENT 'Specifies what type of splitting was done.',
	valid_from          DATE            NULL 	 	COMMENT 'The VALID_FROM column defines when a data record begins to be valid. Typically this is the date of the goods-in receipt and is, at the latest, the date of the goods-in receipt evaluation in DHQ',
	valid_until         DATE            NULL 	 	COMMENT 'The VALID_UNTIL column defines until when a record is valid.',
	item_facility       VARCHAR(20)     NULL 	 	COMMENT '',
	pallet_factor       NUMBER(38,0)    NULL 	 	COMMENT 'Incoming goods pallet factor measured during counting',
	link_posnr          NUMBER(38,0)    NULL 	 	COMMENT 'Line reference number within this goods-in receipt ID.',
	adjust_stock        VARCHAR(1)      NULL 	 	COMMENT 'Indicator for inventory correction in an RS.',
	issue_slip          VARCHAR(30)     NULL 	 	COMMENT 'Delivery slip number.',
	satas_entree        VARCHAR(21)    	NULL 	 	COMMENT 'SATAS number.',
	rcv_unit_type       NUMBER(38,0)    NULL 	 	COMMENT '',
	item_facility2      VARCHAR(20)     NULL 	 	COMMENT '',
	item_facility3      VARCHAR(20)     NULL 	 	COMMENT '',
	decimalcase         NUMBER(38,3)    NULL 	 	COMMENT 'Contents of cases.',
	mengestueck         NUMBER(38,10)   NULL 	 	COMMENT 'Quantity delivered single item_2;',
	pricecond_value     NUMBER(38,10)   NULL 	 	COMMENT 'Value of the weight condition at the time the goods are received.',
	posnr               NUMBER(38,0)    NOT NULL 	COMMENT 'Item_2 no. - consecutive no. Within the ID no.',
	ewm_send_flag       NUMBER(38,0)    NULL 	 	COMMENT 'Flag to mark already sent corrections to EWM',
	cw_caseqty          NUMBER(38,0)    NULL 	 	COMMENT 'Catchweight Case Qty from EWM',
	lpv 				NUMBER(1,0)		NULL		COMMENT '',
	scn 				NUMBER(38,0)	NULL		COMMENT '',
	scaleqty 			NUMBER(30,10)	NULL		COMMENT '',
	dwh_load_id    		NUMBER(38,0) 	NOT NULL 	COMMENT 'Load id',
	dwh_created    		TIMESTAMP 		NOT NULL 	COMMENT 'Record created at',
	dwh_updated    		TIMESTAMP 		NOT NULL 	COMMENT 'Record updated at',
	dwh_valid_from 		DATE 			NOT NULL 	COMMENT 'Valid from date',
	dwh_valid_to   		DATE 			NOT NULL 	COMMENT 'Valid to date',
	deleted_fg     		BOOLEAN 		NOT NULL 	COMMENT 'Flag if record is deleted',
	PRIMARY KEY (client_id, wh_id, artikelnr, id, lagerortnr, posnr, wawi_instanz_kzl, dwh_valid_from)
) COMMENT = 'WAWI - Detailed table for goods-in receipts.'
;